<?php
require_once __DIR__.'/includes/config.php';require_once __DIR__.'/includes/auth.php';sisatRequireRoles([1]);if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Método no permitido.');}
$id=(int)($_POST['id']??0);$accion=$_POST['accion']??'';$comentario=trim($_POST['comentario']??'');if(!$id||!in_array($accion,['APROBAR','RECHAZAR'],true)){header('Location: manage-solicitudes-traslado.php');exit;}
try{$dbh->beginTransaction();$q=$dbh->prepare("SELECT * FROM solicitudes_traslado WHERE id=? AND estado='PENDIENTE' FOR UPDATE");$q->execute([$id]);$s=$q->fetch(PDO::FETCH_ASSOC);if(!$s)throw new RuntimeException('La solicitud ya fue procesada o no existe.');$movimientoId=null;if($accion==='APROBAR'){$q=$dbh->prepare("SELECT a.ubicacion_id,a.estado,u.sede_id FROM activos a LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id WHERE a.id=? FOR UPDATE");$q->execute([$s['activo_id']]);$a=$q->fetch(PDO::FETCH_ASSOC);if(!$a||$a['estado']==='DADO_DE_BAJA_OBSOLETO')throw new RuntimeException('El activo no está disponible.');if((int)$a['ubicacion_id']!==(int)$s['ubicacion_origen_id'])throw new RuntimeException('La ubicación del activo cambió desde que se solicitó. Rechaza esta solicitud y crea una nueva.');$q=$dbh->prepare("SELECT id FROM sedes WHERE id=? AND estado='ACTIVA' FOR UPDATE");$q->execute([$s['sede_destino_id']]);if(!$q->fetchColumn())throw new RuntimeException('La sede destino fue desactivada y ya no está disponible.');$q=$dbh->prepare("SELECT id FROM ubicaciones WHERE sede_id=? AND piso=? AND nombre=? AND area_departamento=? AND estado='ACTIVA' LIMIT 1 FOR UPDATE");$q->execute([$s['sede_destino_id'],$s['piso_destino'],$s['oficina_destino'],$s['departamento_destino']]);$dest=(int)$q->fetchColumn();if(!$dest){$dbh->prepare("INSERT INTO ubicaciones(sede_id,tipo_ubicacion,nombre,piso,area_departamento,estado) VALUES(?,'Oficina',?,?,?,'ACTIVA')")->execute([$s['sede_destino_id'],$s['oficina_destino'],$s['piso_destino'],$s['departamento_destino']]);$dest=(int)$dbh->lastInsertId();}$q=$dbh->prepare("SELECT tipo_asignacion,estado_asignacion,numero_control FROM asignaciones WHERE activo_id=? AND estado_asignacion IN ('ACTIVA','PENDIENTE_FIRMA') FOR UPDATE");$q->execute([$s['activo_id']]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $as){if($as['tipo_asignacion']==='PERSONA')throw new RuntimeException('El activo tiene asignación activa a una persona (' . $as['numero_control'] . '). Regularízala antes de aprobar.');}$dbh->prepare("INSERT INTO movimientos_activos(activo_id,ubicacion_origen_id,ubicacion_destino_id,fecha_movimiento,motivo,autorizado_por,registrado_por,observaciones) VALUES(?,?,?,?,?,?,?,?)")->execute([$s['activo_id'],$a['ubicacion_id'],$dest,$s['fecha_movimiento'],$s['motivo'],$_SESSION['nombre_completo']??$_SESSION['alogin'],(int)$_SESSION['uid'],'Aprobado desde solicitud #'.$id.'. '.($s['observaciones']??'')]);$movimientoId=(int)$dbh->lastInsertId();$up=$dbh->prepare('UPDATE activos SET ubicacion_id=?,fecha_actualizacion=NOW() WHERE id=? AND ubicacion_id=?');$up->execute([$dest,$s['activo_id'],$a['ubicacion_id']]);if($up->rowCount()!==1)throw new RuntimeException('No se pudo actualizar la ubicación.');}
$dbh->prepare('UPDATE solicitudes_traslado SET estado=?,revisado_por=?,fecha_revision=NOW(),comentario_admin=?,movimiento_id=? WHERE id=?')->execute([$accion==='APROBAR'?'APROBADA':'RECHAZADA',(int)$_SESSION['uid'],$comentario?:null,$movimientoId,$id]);$dbh->commit();header('Location: manage-solicitudes-traslado.php?procesada=1');exit;}catch(Throwable $e){if($dbh->inTransaction())$dbh->rollBack();http_response_code(400);echo htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8').'<br><a href="manage-solicitudes-traslado.php">Volver</a>';}
